import {toast} from "react-toastify";
import React, {useEffect, useRef, useState} from "react";
import {Alert, Autocomplete, Box, Button, Chip, CircularProgress, Dialog, DialogActions, DialogContent, DialogTitle, MenuItem, Paper, Stack, Tab, Tabs, TextField, Typography} from "@mui/material";
import {Link, useSearchParams} from "react-router-dom";
import {useAuth} from "../../auth/AuthContext";
import {getApiErrorMessage} from "../../api/errors";
import {MainDiv, PageTitle} from "../../ui/commonStyled/commonStyled";
import {newRequestId} from "../warehouse/receiptDraft";
import {TeamReference, TeamTask, TeamUser, useCreateTeamRoomMutation, useCreateTeamTaskMutation, useGeneralRoomMutation,
    useLazyTeamTaskQuery, useReferenceOptionsQuery, useTeamReferenceQuery, useTeamRoomsQuery, useTeamTasksQuery, useTeamUsersQuery, useUpdateTeamTaskMutation} from "./collaborationApi";
import TeamChat from "./TeamChat";

const statuses: Record<string, string> = {new: "Новая", progress: "В работе", done: "Выполнена", cancelled: "Отменена"};
function ReferenceLink({reference}: {reference: TeamReference | null}) {return reference ? reference.path ? <Button component={Link} to={reference.path} size="small">{reference.title}</Button> : <Typography color="text.secondary" variant="caption">{reference.title}</Typography> : null;}
export default function CollaborationPage() {
    const {user, isCompanyAdmin, isSuperAdmin} = useAuth(); const [params] = useSearchParams();
    const [roomId, setRoomId] = useState(""); const [tab, setTab] = useState(params.get("view") === "tasks" ? 1 : 0);
    const [error, setError] = useState(""); const [roomSearch,setRoomSearch] = useState("");
    const [newRoomOpen, setNewRoomOpen] = useState(false); const [roomTitle, setRoomTitle] = useState(""); const [members, setMembers] = useState<TeamUser[]>([]);
    const [taskOpen, setTaskOpen] = useState(false); const [editing, setEditing] = useState<TeamTask | null>(null); const [title, setTitle] = useState(""); const [description, setDescription] = useState("");
    const [assignee, setAssignee] = useState<TeamUser | null>(null); const [due, setDue] = useState(""); const [status, setStatus] = useState("new"); const [taskPage, setTaskPage] = useState(1);
    const [referenceKind, setReferenceKind] = useState(params.get("kind") ?? "order"); const [referenceSearch, setReferenceSearch] = useState(""); const [search, setSearch] = useState("");
    const [reference, setReference] = useState<TeamReference | null>(null); const [mine, setMine] = useState(false); const [filter, setFilter] = useState("");
    const taskRequestId = useRef(newRequestId()); const generalStarted = useRef(false);
    const users = useTeamUsersQuery(); const rooms = useTeamRoomsQuery(undefined, {pollingInterval: 10000, skipPollingIfUnfocused: true});
    const [general, generalState] = useGeneralRoomMutation(); const [createRoom, createRoomState] = useCreateTeamRoomMutation();
    const tasks = useTeamTasksQuery({roomId, page: taskPage, status: filter || undefined, mine}, {skip: !roomId || tab !== 1, pollingInterval: 5000, skipPollingIfUnfocused: true});
    const [readTask] = useLazyTeamTaskQuery();
    const [createTask, createTaskState] = useCreateTeamTaskMutation(); const [updateTask, updateTaskState] = useUpdateTeamTaskMutation();
    const linked = useTeamReferenceQuery({kind: params.get("kind") ?? "", id: params.get("id") ?? ""}, {skip: !params.get("kind") || !params.get("id")});
    const options = useReferenceOptionsQuery({kind: referenceKind, query: search});
    useEffect(() => {const timer = setTimeout(() => setSearch(referenceSearch), 300); return () => clearTimeout(timer);}, [referenceSearch]);
    useEffect(() => {if (linked.data) setReference(linked.data);}, [linked.data]);
    useEffect(() => {if (rooms.data && !roomId) {const generalRoom = rooms.data.find(room => room.isCompanyRoom); if (generalRoom) setRoomId(generalRoom.id);
        else if (!generalStarted.current) {generalStarted.current = true; void general().unwrap().then(room => setRoomId(room.id)).catch(failure => setError(getApiErrorMessage(failure, "Не удалось открыть общий чат.")));}}}, [rooms.data, roomId, general]);
    useEffect(() => {setTaskPage(1);}, [roomId]);
    const room = rooms.data?.find(item => item.id === roomId);
    const allowedUsers = (users.data ?? []).filter(item => room?.isCompanyRoom || room?.memberIds.includes(item.id));
    const saveRoom = async () => {setError(""); try {const created = await createRoom({title: roomTitle, memberIds: members.map(item => item.id)}).unwrap(); setRoomId(created.id); setNewRoomOpen(false); setMembers([]); setRoomTitle(""); toast.success("Беседа создана.");} catch (failure) {setError(getApiErrorMessage(failure, "Беседа не создана."));}};
    const openTask = (task: TeamTask | null) => {setEditing(task); setTitle(task?.title ?? ""); setDescription(task?.description ?? ""); setStatus(task?.status ?? "new"); setAssignee(users.data?.find(item => item.id === task?.assigneeUserId) ?? null);
        const date = task?.dueAt ? new Date(task.dueAt) : null; setDue(date ? new Date(date.getTime() - date.getTimezoneOffset()*60000).toISOString().slice(0,16) : ""); taskRequestId.current = newRequestId(); setTaskOpen(true);};
    const saveTask = async () => {setError(""); try {const input = {roomId, title, description, assigneeUserId: assignee?.id ?? null, dueAt: due ? new Date(due).toISOString() : null};
        if (editing) await updateTask({...input, id: editing.id, version: editing.version, status}).unwrap();
        else await createTask({...input, requestId: taskRequestId.current, relatedKind: reference?.kind, relatedId: reference?.id}).unwrap(); setTaskOpen(false); toast.success(editing ? "Задача сохранена." : "Задача создана.");
    } catch (failure) {setError(getApiErrorMessage(failure, "Задача не сохранена."));}};
    const canEditFields = !editing || editing.createdByUserId === user?.id || isCompanyAdmin || isSuperAdmin;
    const visibleTasks = tasks.currentData || [];
    const referencePicker = <Stack spacing={1}><TextField select size="small" label="Связать с записью CRM" value={referenceKind} onChange={event => {setReferenceKind(event.target.value); setReference(null); setReferenceSearch("");}}>{[["order","Заказ"],["product","Товар"],["document","Файл для прихода"],["receipt","Приёмка"]].map(([value,label]) => <MenuItem key={value} value={value}>{label}</MenuItem>)}</TextField>
        <Autocomplete options={options.data ?? []} value={reference} isOptionEqualToValue={(a,b) => a.kind === b.kind && a.id === b.id} filterOptions={items => items} getOptionLabel={item => item.title}
            loading={options.isFetching} onChange={(_, item) => setReference(item)} onInputChange={(_, value, reason) => {if (reason === "input") setReferenceSearch(value);}} renderInput={input => <TextField {...input} size="small" label="Поиск по названию или номеру"/>}/>{options.isError && <Typography color="error">Поиск связанных записей недоступен.</Typography>}</Stack>;
    return <MainDiv><Stack spacing={2}><PageTitle>Общение и задачи</PageTitle>{error && <Alert severity="error" onClose={() => setError("")}>{error}</Alert>}{linked.isError && <Alert severity="warning">Связанная запись недоступна.</Alert>}
        <Typography color="text.secondary">Обсуждайте работу в беседах, связывайте сообщения с заказами и превращайте договорённости в задачи.</Typography>
        <Box sx={{display: "grid", gridTemplateColumns: {xs: "1fr", md: "260px minmax(0, 1fr)"}, gap: 2}}><Paper variant="outlined" sx={{p: 2,alignSelf:"start"}}><Stack spacing={1}><Typography variant="h6">Беседы</Typography><Button variant="outlined" onClick={() => setNewRoomOpen(true)}>Новая беседа</Button>
            <TextField size="small" label="Поиск бесед" value={roomSearch} onChange={event=>setRoomSearch(event.target.value)}/>
            {rooms.isLoading && <CircularProgress size={24}/>}
            {rooms.data?.filter(item=>item.title.toLocaleLowerCase().includes(roomSearch.trim().toLocaleLowerCase())).map(item => <Button key={item.id} aria-pressed={roomId===item.id} variant={roomId === item.id ? "contained" : "text"} sx={{justifyContent:"flex-start",textAlign:"left"}} onClick={() => setRoomId(item.id)}><Stack alignItems="flex-start"><span>{item.title}</span><Typography variant="caption" sx={{opacity:0.8}}>{item.isCompanyRoom ? "Вся компания" : `Участников: ${item.memberIds.length}`}</Typography></Stack></Button>)}
            {rooms.data && !rooms.data.some(item=>item.title.toLocaleLowerCase().includes(roomSearch.trim().toLocaleLowerCase())) && <Typography color="text.secondary">Беседы не найдены.</Typography>}
            {rooms.isError && <Alert severity="error">Беседы недоступны. <Button onClick={() => void rooms.refetch()}>Повторить загрузку</Button></Alert>}
            {generalState.isError && <Button onClick={() => {generalStarted.current = false; void general().unwrap().then(item => {setRoomId(item.id); setError("");}).catch(failure => setError(getApiErrorMessage(failure, "Не удалось открыть общий чат.")));}}>Открыть общий чат</Button>}
        </Stack></Paper><Paper variant="outlined" sx={{p: 2, minWidth: 0}}><Typography variant="h6">{room?.title ?? "Загружаем беседу…"}</Typography>
            {room && <Typography color="text.secondary" variant="body2">{room.isCompanyRoom ? `Общий чат · сотрудников: ${users.data?.length ?? "…"}` : `Беседа для участников · ${room.memberIds.length} чел.`}</Typography>}
            <Tabs value={tab} onChange={(_, value) => setTab(value)} aria-label="Раздел беседы"><Tab label="Сообщения"/><Tab label="Задачи"/></Tabs>
            <Box hidden={tab!==0}><TeamChat roomId={roomId} userId={user?.id} active={tab===0} reference={reference} referencePicker={referencePicker} onClearReference={()=>setReference(null)}
                onOpenTask={taskId=>void readTask({roomId,id:taskId}).unwrap().then(task=>{setTab(1);openTask(task);}).catch(failure=>setError(getApiErrorMessage(failure,"Задача недоступна.")))}
                onTaskFromMessage={message=>{openTask(null);setDescription(message.text);setReference(message.reference);}}/></Box>
            {tab === 1 && <Stack spacing={2} mt={2}><Stack direction="row" gap={1} flexWrap="wrap"><Button variant="contained" disabled={!roomId} onClick={() => openTask(null)}>Поставить задачу</Button><Button aria-pressed={mine} variant={mine ? "outlined" : "text"} onClick={() => {setMine(!mine); setTaskPage(1);}}>Мои задачи</Button><TextField select size="small" label="Статус" value={filter} onChange={event => {setFilter(event.target.value); setTaskPage(1);}} sx={{minWidth:150}}><MenuItem value="">Все</MenuItem>{Object.entries(statuses).map(([value,label]) => <MenuItem key={value} value={value}>{label}</MenuItem>)}</TextField></Stack>
                {tasks.isError && <Alert severity="error">Задачи не обновляются. <Button onClick={() => void tasks.refetch()}>Повторить</Button></Alert>}
                {tasks.isFetching && <CircularProgress size={24}/>}
                {!tasks.isFetching && !tasks.isError && !visibleTasks.length && <Alert severity="info">{mine || filter ? "По выбранным фильтрам задач нет." : "Задач пока нет. Нажмите «Поставить задачу» или создайте её из сообщения."}</Alert>}
                {visibleTasks.map(task => <Paper key={task.id} variant="outlined" sx={{p:2}}><Stack direction="row" justifyContent="space-between"><Typography fontWeight={700}>{task.title}</Typography><Chip size="small" color={task.status==="done" ? "success" : task.status==="progress" ? "primary" : "default"} label={statuses[task.status]}/></Stack><Typography sx={{whiteSpace:"pre-wrap"}}>{task.description}</Typography><Typography color="text.secondary">Исполнитель: {task.assigneeName || "Не назначен"}{task.dueAt ? ` · Срок: ${new Date(task.dueAt).toLocaleString("ru-RU")}` : ""}</Typography><ReferenceLink reference={task.reference}/>{(task.createdByUserId === user?.id || task.assigneeUserId === user?.id || isCompanyAdmin || isSuperAdmin) && <Button onClick={() => openTask(task)}>Изменить</Button>}</Paper>)}
                <Stack direction="row"><Button disabled={taskPage===1 || tasks.isFetching} onClick={() => setTaskPage(taskPage-1)}>Назад</Button><Typography alignSelf="center">Страница {taskPage}</Typography><Button disabled={tasks.isFetching || (tasks.currentData?.length ?? 0)<50} onClick={() => setTaskPage(taskPage+1)}>Далее</Button></Stack>
            </Stack>}
        </Paper></Box></Stack>
        <Dialog open={newRoomOpen} onClose={() => setNewRoomOpen(false)} fullWidth><DialogTitle>Новая беседа</DialogTitle><DialogContent><Stack spacing={2} pt={1}>{error && <Alert severity="error">{error}</Alert>}<TextField label="Название" value={roomTitle} inputProps={{maxLength:100}} onChange={event => setRoomTitle(event.target.value)}/><Autocomplete multiple options={(users.data ?? []).filter(item => item.id !== user?.id)} value={members} isOptionEqualToValue={(a,b) => a.id===b.id} getOptionLabel={item => item.name} onChange={(_,value) => setMembers(value)} renderInput={input => <TextField {...input} label="Участники"/>}/><Typography variant="caption">Беседу видят только её участники. Общий чат доступен всей компании.</Typography></Stack></DialogContent><DialogActions><Button onClick={() => setNewRoomOpen(false)}>Отмена</Button><Button disabled={!roomTitle.trim() || !members.length || createRoomState.isLoading} onClick={() => void saveRoom()}>Создать</Button></DialogActions></Dialog>
        <Dialog open={taskOpen} onClose={() => setTaskOpen(false)} fullWidth><DialogTitle>{editing ? "Изменить задачу" : "Поставить задачу"}</DialogTitle><DialogContent><Stack spacing={2} pt={1}>{error && <Alert severity="error">{error}</Alert>}<TextField label="Что нужно сделать" disabled={!canEditFields} value={title} inputProps={{maxLength:200}} onChange={event => setTitle(event.target.value)}/><TextField label="Описание" disabled={!canEditFields} multiline minRows={3} value={description} inputProps={{maxLength:4000}} onChange={event => setDescription(event.target.value)}/><Autocomplete options={allowedUsers} disabled={!canEditFields} value={assignee} isOptionEqualToValue={(a,b) => a.id===b.id} getOptionLabel={item => item.name} onChange={(_,item) => setAssignee(item)} renderInput={input => <TextField {...input} label="Исполнитель"/>}/><TextField type="datetime-local" label="Срок" disabled={!canEditFields} InputLabelProps={{shrink:true}} value={due} onChange={event => setDue(event.target.value)}/>{editing ? <><TextField select label="Статус" value={status} onChange={event => setStatus(event.target.value)}>{Object.entries(statuses).map(([value,label]) => <MenuItem key={value} value={value}>{label}</MenuItem>)}</TextField><ReferenceLink reference={editing.reference}/></> : referencePicker}</Stack></DialogContent><DialogActions><Button onClick={() => setTaskOpen(false)}>Отмена</Button><Button disabled={!title.trim() || createTaskState.isLoading || updateTaskState.isLoading} onClick={() => void saveTask()}>Сохранить</Button></DialogActions></Dialog>
    </MainDiv>;
}
