import React, {useEffect, useRef, useState} from "react";
import {Alert, Avatar, Box, Button, Chip, CircularProgress, Divider, IconButton, InputAdornment, Paper, Stack, TextField, Tooltip, Typography} from "@mui/material";
import SearchIcon from "@mui/icons-material/Search";
import SendIcon from "@mui/icons-material/Send";
import ReplyIcon from "@mui/icons-material/Reply";
import CloseIcon from "@mui/icons-material/Close";
import AddTaskIcon from "@mui/icons-material/AddTask";
import AttachFileIcon from "@mui/icons-material/AttachFile";
import {Link} from "react-router-dom";
import {getApiErrorMessage} from "../../api/errors";
import {newRequestId} from "../warehouse/receiptDraft";
import {TeamMessage, TeamReference, useLazyTeamMessagesQuery, useSendTeamMessageMutation, useTeamMessagesQuery} from "./collaborationApi";

type Props = {roomId: string; userId?: number; active: boolean; reference: TeamReference | null; referencePicker: React.ReactNode;
    onClearReference: () => void; onOpenTask: (id: string) => void; onTaskFromMessage: (message: TeamMessage) => void};
type MessagePayload = {roomId: string; clientMessageId: string; text: string; relatedKind?: string; relatedId?: string};
type ChatDraft = {text: string; reply: TeamMessage | null; pending: MessagePayload | null};
const dateLabel = (date: string) => {
    const day = new Date(date); const today = new Date(); const yesterday = new Date(); yesterday.setDate(today.getDate()-1);
    return day.toDateString() === today.toDateString() ? "Сегодня" : day.toDateString() === yesterday.toDateString() ? "Вчера" : day.toLocaleDateString("ru-RU",{day:"numeric",month:"long",year:"numeric"});
};
const quotePrefix = (message: TeamMessage | null) => message ? `Ответ ${message.senderName}:\n> ${message.text.slice(0,300).replace(/\n/g,"\n> ")}\n\n` : "";

export default function TeamChat({roomId, userId, active, reference, referencePicker, onClearReference, onOpenTask, onTaskFromMessage}: Props) {
    const messages = useTeamMessagesQuery({roomId},{skip:!roomId || !active,pollingInterval:3000,skipPollingIfUnfocused:true});
    const [loadOlder, olderState] = useLazyTeamMessagesQuery(); const [send] = useSendTeamMessageMutation();
    const [older,setOlder] = useState<TeamMessage[]>([]); const [sent,setSent] = useState<TeamMessage[]>([]); const [hasOlder,setHasOlder] = useState(true);
    const [text,setText] = useState(""); const [reply,setReply] = useState<TeamMessage | null>(null); const [search,setSearch] = useState("");
    const [attachOpen,setAttachOpen] = useState(false); const [error,setError] = useState(""); const [feedback,setFeedback] = useState(""); const [sending,setSending] = useState(false);
    const [newCount,setNewCount] = useState(0); const drafts = useRef(new Map<string,ChatDraft>()); const sendingRooms = useRef(new Set<string>());
    const currentRoom = useRef(roomId); currentRoom.current = roomId;
    const scrollRef = useRef<HTMLDivElement>(null); const bottomRef = useRef<HTMLDivElement>(null); const inputRef = useRef<HTMLTextAreaElement>(null);
    const nearBottom = useRef(true); const lastMessageId = useRef(0);
    const draft = () => {let saved = drafts.current.get(roomId); if (!saved) {saved={text:"",reply:null,pending:null};drafts.current.set(roomId,saved);}return saved;};
    const pending = drafts.current.get(roomId)?.pending;
    useEffect(() => {
        const saved = drafts.current.get(roomId);
        setOlder([]);setSent([]);setHasOlder(true);setText(saved?.text || "");setReply(saved?.reply || null);setSearch("");setError("");setFeedback("");setSending(sendingRooms.current.has(roomId));
        nearBottom.current=true;lastMessageId.current=0;setNewCount(0);
    },[roomId]);
    useEffect(() => {
        const saved = drafts.current.get(roomId);
        if (sending || !saved?.pending) return;
        const confirmed = messages.data?.find(message => message.roomId === roomId && message.senderUserId === userId && message.clientMessageId === saved.pending?.clientMessageId);
        if (!confirmed) return;
        // A lost POST response must not leave a saved message frozen as "not sent".
        saved.pending = null; saved.text = ''; saved.reply = null;
        setText(''); setReply(null); setError(''); setFeedback('Сообщение отправлено');
    }, [messages.data, roomId, userId, sending]);
    const all = Array.from(new Map([...older,...sent,...(messages.data || [])].filter(message => message.roomId === roomId).map(message => [message.id,message])).values()).sort((a,b)=>a.id-b.id);
    const newestId = all[all.length-1]?.id || 0;
    useEffect(() => {
        if (!active || !newestId || newestId === lastMessageId.current) return;
        if (nearBottom.current && !search) bottomRef.current?.scrollIntoView?.({behavior:"smooth",block:"nearest"});
        else if (lastMessageId.current) {const arrived=all.filter(message=>message.id>lastMessageId.current).length;setNewCount(count=>count+arrived);}
        lastMessageId.current=newestId;
    // Only newly arrived messages should move the viewport; loading history preserves its position.
    // eslint-disable-next-line react-hooks/exhaustive-deps
    },[newestId,roomId,active]);
    const visible = all.filter(message => `${message.text} ${message.senderName}`.toLocaleLowerCase().includes(search.trim().toLocaleLowerCase()));
    const prefix = quotePrefix(reply);
    const changeText = (value: string) => {draft().text=value;setText(value);setFeedback("");};
    const chooseReply = (message: TeamMessage | null) => {draft().reply=message;setReply(message);inputRef.current?.focus();};
    const sendMessage = async () => {
        if (!roomId || !text.trim() || sendingRooms.current.has(roomId)) return;
        const saved = draft();
        const payload = saved.pending || {roomId,clientMessageId:newRequestId(),text:prefix+text.trim(),relatedKind:reference?.kind,relatedId:reference?.id};
        if (payload.text.length>4000) {setError("Сообщение вместе с цитатой должно быть не длиннее 4000 символов.");return;}
        saved.pending=payload;sendingRooms.current.add(roomId);setSending(true);setError("");setFeedback("");
        try {
            const result = await send(payload).unwrap();
            saved.pending=null;saved.text="";saved.reply=null;
            if (currentRoom.current === roomId) {
                nearBottom.current=true;setText("");setReply(null);setFeedback("Сообщение отправлено");
                if (result.roomId === roomId) setSent(current=>[...current,result]);
            }
        } catch (failure) {
            const status=(failure as {status?:unknown}).status;
            if (typeof status === "number" && status<500) saved.pending=null;
            if (currentRoom.current === roomId) setError(getApiErrorMessage(failure,"Сообщение не отправлено. Повторите отправку."));
        } finally {sendingRooms.current.delete(roomId);if (currentRoom.current === roomId) setSending(false);}
    };
    const history = async () => {
        const element=scrollRef.current;const previousHeight=element?.scrollHeight || 0;const previousTop=element?.scrollTop || 0;
        try {const items=await loadOlder({roomId,before:all[0]?.id}).unwrap();if (currentRoom.current !== roomId) return;
            setOlder(current=>[...items,...current]);setHasOlder(items.length===100);
            requestAnimationFrame(()=>{if (element && currentRoom.current===roomId) element.scrollTop=previousTop+element.scrollHeight-previousHeight;});
        } catch (failure) {if (currentRoom.current===roomId) setError(getApiErrorMessage(failure,"История недоступна."));}
    };
    const frozen = !!pending || sending;
    return <Stack spacing={2} mt={2}>
        <TextField size="small" label="Поиск сообщений" value={search} onChange={event=>setSearch(event.target.value)} helperText="По тексту или автору в загруженной истории"
            InputProps={{startAdornment:<InputAdornment position="start"><SearchIcon fontSize="small"/></InputAdornment>,endAdornment:search ? <IconButton size="small" aria-label="Очистить поиск сообщений" onClick={()=>setSearch("")}><CloseIcon fontSize="small"/></IconButton> : undefined}}/>
        <Box ref={scrollRef} role="log" aria-label="Сообщения беседы" aria-live="polite" sx={{height:{xs:"45vh",md:"48vh"},minHeight:240,overflowY:"auto",px:1,py:2,bgcolor:"background.default",borderRadius:2}}
            onScroll={()=>{const element=scrollRef.current;if (element) {nearBottom.current=element.scrollHeight-element.scrollTop-element.clientHeight<80;if (nearBottom.current) setNewCount(0);}}}>
            {hasOlder && all.length>=100 && <Button fullWidth disabled={olderState.isFetching} onClick={()=>void history()}>{olderState.isFetching ? "Загружаем историю…" : "Более ранние сообщения"}</Button>}
            {messages.isLoading && <Stack alignItems="center" py={3}><CircularProgress size={28}/><Typography>Загружаем сообщения…</Typography></Stack>}
            {!messages.isLoading && !messages.isError && !visible.length && <Stack alignItems="center" spacing={1} py={5}>
                <Typography fontWeight={700}>{search ? "Сообщений по запросу не найдено" : "Начните разговор"}</Typography>
                <Typography color="text.secondary" textAlign="center">{search ? "Измените запрос или загрузите более раннюю историю." : "Напишите коллегам, обсудите заказ или поставьте задачу из сообщения."}</Typography>
            </Stack>}
            {visible.map((message,index)=>{const own=message.senderUserId===userId;const day=dateLabel(message.createdAt);return <React.Fragment key={message.id}>
                {(index===0 || dateLabel(visible[index-1].createdAt)!==day) && <Divider sx={{my:2}}><Typography variant="caption" color="text.secondary">{day}</Typography></Divider>}
                <Stack direction="row" justifyContent={own ? "flex-end" : "flex-start"} alignItems="flex-end" spacing={1} mb={1.5}>
                    {!own && <Avatar sx={{width:30,height:30,fontSize:14,bgcolor:"primary.main"}}>{message.senderName?.slice(0,1).toUpperCase()}</Avatar>}
                    <Paper component="article" aria-label={`Сообщение от ${own ? "вас" : message.senderName}`} elevation={0} sx={{p:1.5,maxWidth:{xs:"90%",md:"80%"},borderRadius:3,bgcolor:own ? "action.selected" : "background.paper",border:"1px solid",borderColor:"divider"}}>
                        <Stack direction="row" justifyContent="space-between" gap={2} mb={0.5}><Typography variant="caption" fontWeight={700}>{own ? "Вы" : message.senderName}</Typography><Typography component="time" dateTime={message.createdAt} variant="caption" color="text.secondary">{new Date(message.createdAt).toLocaleTimeString("ru-RU",{hour:"2-digit",minute:"2-digit"})}</Typography></Stack>
                        <Typography sx={{whiteSpace:"pre-wrap",overflowWrap:"anywhere"}}>{message.text}</Typography>
                        {message.reference && (message.reference.path ? <Button component={Link} to={message.reference.path} size="small">{message.reference.title}</Button> : <Typography variant="caption" color="text.secondary">{message.reference.title}</Typography>)}
                        <Stack direction="row" spacing={0.5} alignItems="center" mt={0.5} flexWrap="wrap">
                            <Button size="small" startIcon={<ReplyIcon/>} disabled={frozen} onClick={()=>chooseReply(message)}>Ответить</Button>
                            {message.taskId ? <Button size="small" startIcon={<AddTaskIcon/>} onClick={()=>onOpenTask(message.taskId!)}>Открыть задачу</Button> : <Button size="small" startIcon={<AddTaskIcon/>} onClick={()=>onTaskFromMessage(message)}>Создать задачу</Button>}
                            {own && <Typography variant="caption" color="text.secondary" sx={{ml:"auto"}}>Отправлено</Typography>}
                        </Stack>
                    </Paper>
                </Stack>
            </React.Fragment>;})}<div ref={bottomRef}/>
        </Box>
        {newCount>0 && <Button variant="outlined" onClick={()=>{nearBottom.current=true;setNewCount(0);bottomRef.current?.scrollIntoView?.({behavior:"smooth",block:"nearest"});}}>Новые сообщения ({newCount}) ↓</Button>}
        {messages.isError && <Alert severity={all.length ? 'warning' : 'error'}>
            {all.length ? 'Временно нет связи с чатом. Загруженные сообщения сохранены, переподключаемся автоматически.' : 'Не удалось загрузить сообщения. Переподключаемся автоматически.'}
            <Button disabled={messages.isFetching} onClick={()=>void messages.refetch()}>Повторить</Button></Alert>}
        <Paper variant="outlined" sx={{p:2,borderRadius:2}}><Stack spacing={1}>
            {reply && <Alert severity="info" icon={<ReplyIcon/>} action={<IconButton aria-label="Отменить ответ" size="small" disabled={frozen} onClick={()=>chooseReply(null)}><CloseIcon fontSize="small"/></IconButton>}>
                <Typography variant="caption" fontWeight={700}>Ответ: {reply.senderName}</Typography><Typography variant="body2" noWrap sx={{maxWidth:360}}>{reply.text}</Typography>
            </Alert>}
            <Stack direction="row" gap={1} alignItems="center" flexWrap="wrap">
                <Button size="small" startIcon={<AttachFileIcon/>} disabled={frozen} onClick={()=>setAttachOpen(!attachOpen)}>{attachOpen ? "Скрыть связь с CRM" : "Связать с записью CRM"}</Button>
                {reference && <Chip size="small" label={reference.title} disabled={frozen} onDelete={onClearReference}/>}
            </Stack>
            {attachOpen && !frozen && referencePicker}
            {error && <Alert severity="error">{error}</Alert>}
            <Box component="form" onSubmit={event=>{event.preventDefault();void sendMessage();}}>
                <TextField fullWidth multiline minRows={2} maxRows={6} inputRef={inputRef} label="Сообщение" placeholder="Напишите коллегам…" value={text} disabled={frozen || !roomId}
                    inputProps={{maxLength:Math.max(0,4000-prefix.length)}} onChange={event=>changeText(event.target.value)}
                    onKeyDown={event=>{if (event.key==="Enter" && !event.shiftKey && !event.nativeEvent.isComposing) {event.preventDefault();void sendMessage();}}}/>
                <Stack direction="row" justifyContent="space-between" alignItems="center" gap={1} mt={1} flexWrap="wrap">
                    <Typography variant="caption" color="text.secondary">Enter — отправить · Shift+Enter — новая строка · {text.length+prefix.length}/4000</Typography>
                    <Tooltip title={sending ? "Отправляем сообщение" : "Отправить сообщение"}><span><Button type="submit" variant="contained" startIcon={sending ? <CircularProgress size={16} color="inherit"/> : <SendIcon/>} disabled={!roomId || !text.trim() || sending}>{sending ? "Отправляем…" : pending ? "Повторить отправку" : "Отправить"}</Button></span></Tooltip>
                </Stack>
                {feedback && <Typography role="status" variant="caption" color="success.main">{feedback}</Typography>}
            </Box>
        </Stack></Paper>
    </Stack>;
}
